from __future__ import annotations

from capacity_domain import MeetingRunState, ParticipantSeat
from capacity_ledger import hall_counts_tuple, total_heads
from entitlement_clock import (
    entitlement_jump_magnitude,
    explain_entitlement_modes,
    freeze_baseline_ceiling,
    live_entitlement_ceiling,
    post_grace_entitlement_reached,
)


def summarize_capacity_run(
    state: MeetingRunState,
    participants: list[ParticipantSeat],
    now_ts: int,
) -> dict[str, object]:
    live = live_entitlement_ceiling(state, int(now_ts))
    main_n, ovf_n = hall_counts_tuple(participants)
    return {
        "meeting_id": state.meeting_id,
        "live_ceiling": live,
        "session_start_ceiling": state.session_start_ceiling,
        "pending_ceiling": state.pending_ceiling,
        "grace_expires_at_ts": state.grace_expires_at_ts,
        "post_grace": post_grace_entitlement_reached(state, int(now_ts)),
        "main_hall": main_n,
        "overflow": ovf_n,
        "total": total_heads(participants),
        "headroom": max(0, live - main_n),
        "entitlement_mode": explain_entitlement_modes(state, int(now_ts)),
        "jump": entitlement_jump_magnitude(state),
        "billing_snapshot_cap": freeze_baseline_ceiling(state),
    }


def audit_room_balance_ok(summary: dict[str, object]) -> bool:
    return int(summary["main_hall"]) + int(summary["overflow"]) == int(summary["total"])


def audit_headline(summary: dict[str, object]) -> str:
    return f"{summary['meeting_id']} main={summary['main_hall']} cap={summary['live_ceiling']}"


def support_pack_summary(summary: dict[str, object]) -> str:
    return f"{summary['entitlement_mode']}|ovf={summary['overflow']}"


def compare_live_to_pending(summary: dict[str, object]) -> bool:
    if summary["pending_ceiling"] is None:
        return True
    return int(summary["live_ceiling"]) <= int(summary["pending_ceiling"])


def zero_headroom_flag(summary: dict[str, object]) -> bool:
    return int(summary["headroom"]) == 0


def export_flat_metrics(summary: dict[str, object]) -> dict[str, int]:
    return {
        "main": int(summary["main_hall"]),
        "overflow": int(summary["overflow"]),
        "live": int(summary["live_ceiling"]),
    }


def incident_severity_stub(summary: dict[str, object]) -> str:
    if int(summary["overflow"]) > 0 and int(summary["headroom"]) > 0:
        return "drain_missed"
    if int(summary["overflow"]) > 0:
        return "at_capacity"
    return "nominal"


def audit_iso_timestamp_placeholder(now_ts: int) -> str:
    return f"ts={int(now_ts)}"


def rolling_jump_bps(jump: int) -> int:
    return int(jump) * 10


def dual_write_guard(summary_a: dict[str, object], summary_b: dict[str, object]) -> bool:
    keys = ("main_hall", "overflow", "total")
    return all(summary_a[k] == summary_b[k] for k in keys)


def telemetry_digest(summary: dict[str, object]) -> str:
    return f"m{summary['main_hall']}o{summary['overflow']}l{summary['live_ceiling']}"


def capacity_audit_engine_version() -> str:
    return "cap-audit-v2"


def snapshot_differs_from_live(summary: dict[str, object]) -> bool:
    return int(summary["billing_snapshot_cap"]) != int(summary["live_ceiling"])


def format_escalation(meeting_id: str, mode: str) -> str:
    return f"esc[{meeting_id.strip()}:{mode}]"


def audit_rows_non_negative(summary: dict[str, object]) -> bool:
    return min(int(summary["main_hall"]), int(summary["overflow"]), int(summary["total"])) >= 0


def meeting_customer_segment_stub(segment: str) -> str:
    return segment.strip().lower() or "default"

