from __future__ import annotations

from dataclasses import dataclass, field
from typing import Literal

HallName = Literal["main", "overflow"]


class CapacityModelError(ValueError):
    """Invalid capacity or participant material."""


def _clean(label: str, value: str) -> str:
    token = str(value).strip()
    if not token:
        raise CapacityModelError(f"{label} required")
    return token


def _nonneg_int(label: str, value: int) -> int:
    if value < 0:
        raise CapacityModelError(f"{label} must be non-negative")
    return value


@dataclass
class MeetingRunState:
    """Mutable meeting-wide capacity timeline (session snapshot + scheduled upgrade)."""

    meeting_id: str
    session_start_ceiling: int
    pending_ceiling: int | None = None
    grace_expires_at_ts: int | None = None

    def __post_init__(self) -> None:
        mid = _clean("meeting_id", self.meeting_id)
        cap = _nonneg_int("session_start_ceiling", int(self.session_start_ceiling))
        if cap == 0:
            raise CapacityModelError("session_start_ceiling must be positive")
        self.meeting_id = mid
        self.session_start_ceiling = cap
        if self.pending_ceiling is not None and self.pending_ceiling < cap:
            raise CapacityModelError("pending_ceiling cannot shrink below session start")
        if self.pending_ceiling is not None:
            self.pending_ceiling = int(self.pending_ceiling)
        if self.grace_expires_at_ts is not None:
            self.grace_expires_at_ts = int(self.grace_expires_at_ts)


@dataclass
class ParticipantSeat:
    """One occupant in either hall."""

    user_id: str
    joined_at_ts: int
    hall: HallName

    def __post_init__(self) -> None:
        uid = _clean("user_id", self.user_id)
        ts = int(self.joined_at_ts)
        if ts < 0:
            raise CapacityModelError("joined_at_ts invalid")
        if self.hall not in ("main", "overflow"):
            raise CapacityModelError("hall must be main or overflow")
        self.user_id = uid
        self.joined_at_ts = ts


def meeting_run_fingerprint(state: MeetingRunState) -> str:
    pend = state.pending_ceiling or 0
    grace = state.grace_expires_at_ts or 0
    return f"{state.meeting_id}:{state.session_start_ceiling}:{pend}:{grace}"


def describe_hall(hall: HallName) -> str:
    return "main_hall" if hall == "main" else "overflow_lane"


def seat_row_label(seat: ParticipantSeat) -> str:
    return f"{seat.user_id}@{seat.hall}:{seat.joined_at_ts}"


def sort_key_fifo(seat: ParticipantSeat) -> tuple[int, str]:
    return seat.joined_at_ts, seat.user_id


def clone_state_outline(state: MeetingRunState) -> dict[str, object]:
    return {
        "meeting_id": state.meeting_id,
        "start_cap": state.session_start_ceiling,
        "pending": state.pending_ceiling,
        "grace_end": state.grace_expires_at_ts,
    }


def validate_pending_pair(state: MeetingRunState) -> None:
    if state.pending_ceiling is None and state.grace_expires_at_ts is not None:
        raise CapacityModelError("grace without pending ceiling")
    if state.pending_ceiling is not None and state.grace_expires_at_ts is None:
        raise CapacityModelError("pending ceiling without grace end")


def upgrade_is_armed(state: MeetingRunState) -> bool:
    return state.pending_ceiling is not None and state.grace_expires_at_ts is not None


def minutes_from_seconds(seconds: int) -> int:
    if seconds < 0:
        raise CapacityModelError("seconds must be non-negative")
    return seconds // 60


def ceiling_delta_if_applied(state: MeetingRunState) -> int:
    if state.pending_ceiling is None:
        return 0
    return int(state.pending_ceiling) - int(state.session_start_ceiling)


def format_support_meeting_line(state: MeetingRunState) -> str:
    return f"{state.meeting_id} cap0={state.session_start_ceiling} pending={state.pending_ceiling}"


def hall_toggle_overflow_if_full(is_main_full: bool) -> HallName:
    return "overflow" if is_main_full else "main"


def participant_hour_bucket(joined_at_ts: int) -> int:
    return joined_at_ts // 3600


def merge_hall_counts(main_n: int, ovf_n: int) -> int:
    return main_n + ovf_n


def cap_usage_ratio(seated: int, ceiling: int) -> float:
    if ceiling <= 0:
        raise CapacityModelError("ceiling must be positive")
    return round(min(seated / ceiling, 1.0), 4)


def assert_known_hall(hall: str) -> HallName:
    if hall not in ("main", "overflow"):
        raise CapacityModelError("unknown hall")
    return hall  # type: ignore[return-value]


def snapshot_serial_suffix(state: MeetingRunState) -> str:
    """Cheap pseudo-version for log correlation."""

    base = len(state.meeting_id) + state.session_start_ceiling
    extra = (state.pending_ceiling or 0) % 97
    return f"sn-{base + extra}"


def dummy_rebind_placeholder() -> str:
    return "no_rebind_in_this_kata"


@dataclass
class CapacityTelemetry:
    """Optional metrics bag tests may ignore."""

    last_router_ts: int = 0
    last_drain_ts: int = 0
    notes: list[str] = field(default_factory=list)


def append_note(telemetry: CapacityTelemetry, line: str) -> None:
    telemetry.notes.append(str(line).strip())


def meeting_pair_key(tenant_id: str, meeting_id: str) -> str:
    return f"{_clean('tenant_id', tenant_id)}|{_clean('meeting_id', meeting_id)}"


def coerce_unix_ts(raw: int | float) -> int:
    if float(raw) != int(raw):
        raise CapacityModelError("timestamp must be whole seconds")
    return int(raw)

