from __future__ import annotations

from capacity_domain import CapacityModelError, MeetingRunState, ParticipantSeat
from capacity_ledger import (
    available_main_slots,
    count_main_hall,
    count_overflow,
    roster_size_matches,
    total_heads,
)
from entitlement_clock import live_entitlement_ceiling


def assert_consistent_hall_counts(participants: list[ParticipantSeat]) -> None:
    m = count_main_hall(participants)
    o = count_overflow(participants)
    if not roster_size_matches(m, o, participants):
        raise CapacityModelError("hall totals diverge")


def assert_main_within_ceiling(state: MeetingRunState, participants: list[ParticipantSeat], now_ts: int) -> None:
    cap = live_entitlement_ceiling(state, int(now_ts))
    if count_main_hall(participants) > cap:
        raise CapacityModelError("main hall exceeds ceiling")


def assert_no_phantom_seats(state: MeetingRunState, participants: list[ParticipantSeat], now_ts: int) -> None:
    if available_main_slots(participants, live_entitlement_ceiling(state, int(now_ts))) < 0:
        raise CapacityModelError("phantom negative headroom")


def invariant_passes(state: MeetingRunState, participants: list[ParticipantSeat], now_ts: int) -> bool:
    try:
        assert_consistent_hall_counts(participants)
        assert_main_within_ceiling(state, participants, now_ts)
        assert_no_phantom_seats(state, participants, now_ts)
    except CapacityModelError:
        return False
    return True


def hard_cap_crosscheck(ceiling: int, main_n: int) -> bool:
    return main_n <= ceiling


def participant_index_bounds(participants: list[ParticipantSeat], limit: int) -> bool:
    return total_heads(participants) <= limit


def explain_invariant_failure(code: str) -> str:
    return f"inv_fail:{code}"


def dual_hall_xor_guard(participants: list[ParticipantSeat]) -> None:
    for p in participants:
        if p.hall not in ("main", "overflow"):
            raise CapacityModelError("hall domain")


def freeze_invariant_set() -> frozenset[str]:
    return frozenset({"halls", "ceiling", "phantom"})


def ledger_size_matches_union(main_n: int, ovf_n: int, total: int) -> bool:
    return main_n + ovf_n == total


def strict_positive_meeting_ceiling(cap: int) -> None:
    if int(cap) < 1:
        raise CapacityModelError("ceiling must be positive")


def invariant_engine_revision() -> str:
    return "inv-2026-05"


def cross_meeting_isolation_stub(left_id: str, right_id: str) -> bool:
    return left_id.strip() != right_id.strip()


def replay_safe_token() -> str:
    return "replay-ok"


def assert_overflow_non_negative(participants: list[ParticipantSeat]) -> None:
    if count_overflow(participants) < 0:
        raise CapacityModelError("negative overflow impossible")

