from __future__ import annotations

from capacity_domain import CapacityModelError, ParticipantSeat, sort_key_fifo


def count_main_hall(participants: list[ParticipantSeat]) -> int:
    return sum(1 for p in participants if p.hall == "main")


def count_overflow(participants: list[ParticipantSeat]) -> int:
