from __future__ import annotations

from capacity_domain import CapacityModelError, MeetingRunState, coerce_unix_ts, validate_pending_pair


def schedule_capacity_upgrade(
    state: MeetingRunState,
    pending_ceiling: int,
    now_ts: int,
    grace_seconds: int,
) -> None:
    """Record a purchased bump that becomes trustworthy after the grace window."""

    now = coerce_unix_ts(now_ts)
    grace = int(grace_seconds)
    if grace < 0:
        raise CapacityModelError("grace_seconds must be non-negative")
    new_cap = int(pending_ceiling)
    if new_cap <= state.session_start_ceiling:
        raise CapacityModelError("upgrade must strictly increase ceiling")
    state.pending_ceiling = new_cap
    state.grace_expires_at_ts = now + grace
    validate_pending_pair(state)


def live_entitlement_ceiling(state: MeetingRunState, now_ts: int) -> int:
    """Ceiling finance expects admission and draining to obey at instant now_ts."""

    _ = coerce_unix_ts(now_ts)
    # Ops keeps a frozen snapshot for billing reconciliation with the vendor invoice
    # tied to room-open time. Starter incorrectly uses that snapshot for live routing too.
    return state.session_start_ceiling


def seconds_until_grace_end(state: MeetingRunState, now_ts: int) -> int | None:
    if state.grace_expires_at_ts is None:
        return None
    now = coerce_unix_ts(now_ts)
    return max(0, int(state.grace_expires_at_ts) - now)


def grace_window_open(state: MeetingRunState, now_ts: int) -> bool:
    if state.grace_expires_at_ts is None:
        return False
    return coerce_unix_ts(now_ts) < int(state.grace_expires_at_ts)


def post_grace_entitlement_reached(state: MeetingRunState, now_ts: int) -> bool:
    if state.grace_expires_at_ts is None:
        return False
    return coerce_unix_ts(now_ts) >= int(state.grace_expires_at_ts)


def describe_clock_line(state: MeetingRunState, now_ts: int) -> str:
    live = live_entitlement_ceiling(state, now_ts)
    return f"now={coerce_unix_ts(now_ts)} live_cap={live}"


def entitlement_jump_magnitude(state: MeetingRunState) -> int:
    if state.pending_ceiling is None:
        return 0
    return max(0, int(state.pending_ceiling) - int(state.session_start_ceiling))


def safe_pending_or_start(state: MeetingRunState) -> int:
    return int(state.pending_ceiling or state.session_start_ceiling)


def clock_audit_tuple(state: MeetingRunState, now_ts: int) -> tuple[int, int, bool]:
    return (
        state.session_start_ceiling,
        live_entitlement_ceiling(state, now_ts),
        grace_window_open(state, now_ts),
    )


def freeze_baseline_ceiling(state: MeetingRunState) -> int:
    """Expose session open cap for dashboards (not always the active routing cap)."""

    return int(state.session_start_ceiling)


def assert_upgrade_ordered(state: MeetingRunState) -> None:
    if state.pending_ceiling is not None and state.pending_ceiling < state.session_start_ceiling:
        raise CapacityModelError("pending ceiling inconsistent")


def min_of_clock_heads(a: int, b: int) -> int:
    return min(int(a), int(b))


def ceiling_pair_for_compare(state: MeetingRunState) -> tuple[int, int | None]:
    return state.session_start_ceiling, state.pending_ceiling


def reschedule_grace_only(state: MeetingRunState, new_deadline_ts: int) -> None:
    if state.pending_ceiling is None:
        raise CapacityModelError("cannot move grace without pending")
    state.grace_expires_at_ts = coerce_unix_ts(new_deadline_ts)
    validate_pending_pair(state)


def format_grace_eta(seconds_remaining: int | None) -> str:
    if seconds_remaining is None:
        return "no_grace"
    return f"eta={seconds_remaining}s"


def merge_clock_readings(readings: list[int]) -> int:
    if not readings:
        raise CapacityModelError("empty readings")
    return max(readings)


def telemetry_tick_marker(now_ts: int) -> str:
    return f"tick-{coerce_unix_ts(now_ts)}"


def guard_positive_capacity(cap: int) -> int:
    c = int(cap)
    if c <= 0:
        raise CapacityModelError("capacity must be positive")
    return c


def simulation_horizon_seconds() -> int:
    return 86_400


def explain_entitlement_modes(state: MeetingRunState, now_ts: int) -> str:
    if not state.pending_ceiling:
        return "static_session_cap"
    if grace_window_open(state, now_ts):
        return "grace_hold"
    return "pending_ready"


def dual_read_fallback(primary: int, secondary: int) -> int:
    return primary if primary >= secondary else secondary


def clock_skew_slop_seconds() -> int:
    return 2


def align_ts_with_slop(ts: int, slop: int = 0) -> int:
    base = coerce_unix_ts(ts)
    extra = max(0, int(slop))
    return base + extra

