from __future__ import annotations

from capacity_domain import CapacityModelError


def normalize_meeting_slug(raw: str) -> str:
    token = str(raw).strip().lower()
    if not token:
        raise CapacityModelError("meeting slug required")
    if " " in token:
        raise CapacityModelError("meeting slug cannot contain spaces")
    return token


def meeting_key_with_tenant(tenant_code: str, meeting_slug: str) -> str:
    t = normalize_meeting_slug(tenant_code)
    m = normalize_meeting_slug(meeting_slug)
    return f"{t}::{m}"


def obfuscate_meeting_id(public_id: str) -> str:
    pid = str(public_id).strip()
    if len(pid) < 4:
        return "***"
    return f"{pid[:2]}…{pid[-2:]}"


def meeting_id_numeric_guard(value: str) -> bool:
    v = str(value).strip()
    return v.isdigit() and len(v) >= 9


def format_regional_shard(region: str, meeting_id: str) -> str:
    r = str(region).strip().upper()
    if not r:
        raise CapacityModelError("region required")
    mid = str(meeting_id).strip()
    if not mid:
        raise CapacityModelError("meeting_id required")
    return f"{r}/{mid}"


def meeting_pair_collision_safe(left: str, right: str) -> bool:
    return normalize_meeting_slug(left) != normalize_meeting_slug(right)


def short_meeting_label(meeting_id: str, max_len: int = 12) -> str:
    mid = str(meeting_id).strip()
    if len(mid) <= max_len:
        return mid
    return mid[: max_len - 1] + "…"


def join_bridge_scope(tenant: str, bridge_id: str) -> str:
    return f"{tenant.strip()}|b={bridge_id.strip()}"


def meeting_checksum_stub(meeting_id: str) -> int:
    return sum(ord(c) for c in meeting_id) % 255


def meeting_key_length_ok(key: str, minimum: int) -> bool:
    return len(key.strip()) >= int(minimum)


def split_scope_key(key: str) -> tuple[str, str]:
    if "::" not in key:
        raise CapacityModelError("scope key malformed")
    left, _, right = key.partition("::")
    return left, right


def meeting_catalog_index(meeting_id: str, bucket: int) -> str:
    return f"{bucket:03d}/{meeting_id.strip()}"


def scrub_join_code(raw: str) -> str:
    return "".join(ch for ch in str(raw) if ch.isalnum())


def meeting_keying_version() -> str:
    return "meet-key-v1"


def assert_has_region(region: str | None) -> str:
    if region is None or not str(region).strip():
        raise CapacityModelError("region missing")
    return str(region).strip()

