overflow_drainer.py.as-is:
from __future__ import annotations

from capacity_domain import CapacityModelError, MeetingRunState, ParticipantSeat
from capacity_ledger import (
    available_main_slots,
    count_main_hall,
    count_overflow,
    list_overflow_fifo_ordered,
    move_to_main,
)
from entitlement_clock import live_entitlement_ceiling


def drain_overflow_fifo(state: MeetingRunState, participants: list[ParticipantSeat], now_ts: int) -> int:
    """Move overflow participants into main while seats exist under the live ceiling."""

    cap = live_entitlement_ceiling(state, int(now_ts))
    moved = 0
    safety = 0
    while safety < 10_000:
        safety += 1
        free = available_main_slots(participants, cap)
        if free <= 0:
            break
        nxt = list_overflow_fifo_ordered(participants)
        if not nxt:
            break
        candidate = nxt[0]
        move_to_main(candidate)
        moved += 1
    if safety >= 10_000:
        raise CapacityModelError("drain loop guard tripped")
    return moved


def drain_until_balanced(state: MeetingRunState, participants: list[ParticipantSeat], now_ts: int) -> dict[str, int]:
    total_moved = drain_overflow_fifo(state, participants, now_ts)
    return {
        "moved": total_moved,
        "main": count_main_hall(participants),
        "overflow": count_overflow(participants),
        "cap": live_entitlement_ceiling(state, int(now_ts)),
    }


