def route_new_join(
    state: MeetingRunState,
    participants: list[ParticipantSeat],
    user_id: str,
    now_ts: int,
) -> ParticipantSeat:
    """Decide main vs overflow using entitlement clock + ledger headroom."""

    uid = str(user_id).strip()
    if not uid:
        raise CapacityModelError("user_id required")
    ensure_unique_user(participants, uid)
    cap = live_entitlement_ceiling(state, int(now_ts))
    free = available_main_slots(participants, cap)
    hall: HallName = "main" if free > 0 else "overflow"
    seat = ParticipantSeat(uid, int(now_ts), hall)
    participants.append(seat)
