    for uid in user_ids:
        out.append(route_new_join(state, participants, uid, now_ts))
    return out


def peek_routed_hall(state: MeetingRunState, participants: list[ParticipantSeat], now_ts: int) -> str:
    cap = live_entitlement_ceiling(state, int(now_ts))
    if available_main_slots(participants, cap) > 0:
        return "main"
    return "overflow"


def router_pressure_line(state: MeetingRunState, participants: list[ParticipantSeat], now_ts: int) -> str:
    cap = live_entitlement_ceiling(state, int(now_ts))
    m = count_main_hall(participants)
    return f"cap={cap} main={m} ovf={count_overflow(participants)}"


def admission_token_stub(user_id: str, hall: str) -> str:
    return f"{user_id}:{hall}"


def join_ts_monotonic_check(prev_ts: int, new_ts: int) -> None:
    if new_ts < prev_ts:
        raise CapacityModelError("non-monotonic join timestamps in fixture")


def estimate_next_join_delay(load_ratio: float) -> int:
    if load_ratio < 0:
        raise CapacityModelError("load_ratio invalid")
    return int(min(30, max(0, load_ratio * 10)))


