    tail = sorted(participants, key=lambda p: (p.joined_at_ts, p.user_id))[-limit:]
    return ",".join(p.user_id for p in tail)


def router_idle_heads(main_n: int, ovf_n: int) -> bool:
    return main_n == 0 and ovf_n == 0


def meeting_scope_line(tenant: str, meeting_id: str) -> str:
    return f"{tenant.strip()}::{meeting_id.strip()}"

