from __future__ import annotations

from capacity_domain import CapacityModelError, MeetingRunState
from entitlement_clock import schedule_capacity_upgrade


def apply_purchased_upgrade(
    state: MeetingRunState,
    new_ceiling: int,
    now_ts: int,
    grace_seconds: int,
    purchase_token: str,
) -> str:
    """Thin façade used by billing jobs; keeps upgrade + audit token together."""

    tok = str(purchase_token).strip()
    if not tok:
        raise CapacityModelError("purchase_token required")
    schedule_capacity_upgrade(state, int(new_ceiling), int(now_ts), int(grace_seconds))
    return f"upgrade_applied:{tok}"


def replay_upgrade_safe(state: MeetingRunState, token: str) -> bool:
    """Return whether a billing replay should be treated as duplicate."""

    return bool(state.pending_ceiling) and token in ("replay", "dup")


def upgrade_facade_version() -> str:
    return "upg-facade-v1"


def bundle_upgrade_command(meeting_id: str, cap: int, grace: int) -> dict[str, object]:
    mid = str(meeting_id).strip()
    if not mid:
        raise CapacityModelError("meeting_id required")
    return {"meeting_id": mid, "cap": int(cap), "grace_seconds": int(grace)}


def explain_facade_action(action: str) -> str:
    a = str(action).strip().lower()
    if a not in {"schedule", "noop"}:
        raise CapacityModelError("unknown facade action")
    return f"facade:{a}"


def purchase_token_fingerprint(tok: str) -> str:
    t = str(tok).strip()
    return f"pt-{len(t)}-{t[:3]}"


def guard_monotonic_ceiling(previous: int, incoming: int) -> None:
    if int(incoming) <= int(previous):
        raise CapacityModelError("incoming ceiling must increase")


def schedule_stub_payload(cap: int, grace: int) -> bytes:
    return f"{cap}:{grace}".encode("utf-8")


def upgrade_manifest_line(state: MeetingRunState) -> str:
    pend = state.pending_ceiling or 0
    grace = state.grace_expires_at_ts or 0
    return f"{state.meeting_id}:{pend}:{grace}"


def facade_support_hint(meeting_id: str, issue: str) -> str:
    return f"{meeting_id.strip()}::{issue.strip()}"


def double_schedule_blocker(already_pending: bool) -> None:
    if already_pending:
        raise CapacityModelError("pending upgrade already armed")


def tenant_upgrade_scope(tenant: str) -> str:
    return f"tnt={tenant.strip().lower()}"


def upgrade_correlation_stub(left: int, right: int) -> int:
    return int(left) ^ int(right)


def command_ttl_seconds() -> int:
    return 300


def noop_facade_ping() -> str:
    return "pong"

